(** 1RB0LD_1LC1RA_0RB1LD_1RA1LC *)
(** 1RB0LD_1LC1RA_0RB1LD_1RA1LC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LD_1LC1RA_0RB1LD_1RA1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StC end.

(** Its mirror 1LB0RD_1RC1LA_0LB1RD_1LA1RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LD_1LC1RA_0RB1LD_1RA1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S1 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LD_1LC1RA_0RB1LD_1RA1LC : list Instr := [(StD, S0)].
Definition tmw_1RB0LD_1LC1RA_0RB1LD_1RA1LC : TM := tm_wrap_trs tmm_1RB0LD_1LC1RA_0RB1LD_1RA1LC pins_1RB0LD_1LC1RA_0RB1LD_1RA1LC.
