    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_0RD0LC_1RA1RA B0_1RB0LD_1LC1RA_0RD0LC_1RA1RA B1_1RB0LD_1LC1RA_0RD0LC_1RA1RA 4 10 p j' [] []).
