  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_1LC1RC_0RB1LD_1RC1LA
      with (l := [SWin 3]).
    vm_compute; reflexivity.
Qed.

