Lemma lapi_1RB0LD_1RC0LA_1LA1RB_0RB0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LD_1RC0LA_1LA1RB_0RB0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 4), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB0LD_1RC0LA_1LA1RB_0RB0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB0LD_1RC0LA_1LA1RB_0RB0LD Z0_1RB0LD_1RC0LA_1LA1RB_0RB0LD Z1_1RB0LD_1RC0LA_1LA1RB_0RB0LD 0 4
             run_z_1RB0LD_1RC0LA_1LA1RB_0RB0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB0LD_1RC0LA_1LA1RB_0RB0LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 8), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j' P1_1RB0LD_1RC0LA_1LA1RB_0RB0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB0LD_1RC0LA_1LA1RB_0RB0LD P0_1RB0LD_1RC0LA_1LA1RB_0RB0LD P1_1RB0LD_1RC0LA_1LA1RB_0RB0LD 4 8
             run_p_1RB0LD_1RC0LA_1LA1RB_0RB0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0LD_1RC0LA_1LA1RB_0RB0LD : forall p j, cview p = (S j, None) ->
