(** ** Bootstrap *)

Lemma bootq_1RB0LD_1RC0LA_1LA1RB_0RB0LD : stepn tmm_1RB0LD_1RC0LA_1LA1RB_0RB0LD 20 InitES = Some (lift (Cc 1)).
