Lemma fire_1RB0LD_1RC0LC_1LA1RB_0RB0LD : forall t, ~ In t pins_1RB0LD_1RC0LC_1LA1RB_0RB0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
