  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_1RC0RD_1LA1RB_0RB0LD
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 3]).
