Lemma gz_1RB0LD_1RC1RB_1LD1RA_0RC0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_1RB0LD_1RC1RB_1LD1RA_0RC0LD /\
