    rewrite (srun_sound tm false true chz_1RB0LD_1RC1RB_1LD1RA_0RC0LD Z0_1RB0LD_1RC1RB_1LD1RA_0RC0LD Z1_1RB0LD_1RC1RB_1LD1RA_0RC0LD 0 2
               run_z_1RB0LD_1RC1RB_1LD1RA_0RC0LD (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0
