  apply (lap_qh_stage tmm_1RB0LD_1RC1RB_1LD1RA_0RC0LD pins_1RB0LD_1RC1RB_1LD1RA_0RC0LD Cc 1 41 32779478).
  - exact bootq_1RB0LD_1RC1RB_1LD1RA_0RC0LD.
