    apply (lap_of_run tm Cc true true cho_1RB0RA_1LC1RA_1LD0LC_0RD0RB B0_1RB0RA_1LC1RA_1LD0LC_0RD0RB B1_1RB0RA_1LC1RA_1LD0LC_0RD0RB 4 8 p j' [] []).
